'use strict';

const fs = require('fs');
const path = require('path');

/**
 * Assets oficiais embutidos para e-mails do Coliseu Transporte / Coliseu Sistemas.
 * Garante que imagens críticas de comunicados e cobranças NUNCA quebrem por 404
 * mesmo em novos containers Docker ou sem persistência em disco.
 */

const COBRANCA_ALERTA_BASE64 = '';

let _cachedBuffer = null;

function getCobrancaAlertaBuffer() {
    if (_cachedBuffer) return _cachedBuffer;

    // Tenta carregar do disco primeiro se existir
    const possiblePaths = [
        path.join(__dirname, '../../public/assets/cobranca_alerta.png'),
        path.join(__dirname, '../public/assets/cobranca_alerta.png'),
        path.join(__dirname, '../../public/cobranca_alerta.png'),
        path.join('/tmp', 'cobranca_alerta.png')
    ];

    for (const p of possiblePaths) {
        try {
            if (fs.existsSync(p)) {
                _cachedBuffer = fs.readFileSync(p);
                return _cachedBuffer;
            }
        } catch (_) {}
    }

    // Fallback garantido da memória
    _cachedBuffer = Buffer.from(COBRANCA_ALERTA_BASE64, 'base64');
    return _cachedBuffer;
}

module.exports = {
    COBRANCA_ALERTA_BASE64,
    getCobrancaAlertaBuffer
};
